-- =====================================================
-- 02_validate_cleanup_targets.sql
-- Contagem de registros que serão deletados pelo seed
-- SOMENTE SELECT — nunca executar DELETE aqui
-- =====================================================

-- Obras demo
SELECT 'obras' AS tabela, count(*) AS registros
FROM obras
WHERE id IN (
  'a1000000-0000-0000-0000-000000000001',
  'a2000000-0000-0000-0000-000000000002',
  'a3000000-0000-0000-0000-000000000003'
);

